package taskindex_test

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/tylinux/nex/go/internal/adapters/taskindex"
)

// fixturesDir holds go/testdata/taskindex/migrations/<version>.sqlite — the
// per-version databases recorded from the Node implementation (step 3.10.4
// "migration fixtures for every version"). They are generated by
// `go test ./internal/adapters/taskindex/ -run RecordFixtures` after a Node
// migration run; regenerate deliberately, never by hand.
func fixturesDir(t *testing.T) string {
	t.Helper()
	return filepath.Join("..", "..", "..", "testdata", "taskindex", "migrations")
}

func openMigrated(t *testing.T, path string) *sql.DB {
	t.Helper()
	db, err := taskindex.Open(context.Background(), path, nil)
	if err != nil {
		t.Fatalf("open %s: %v", path, err)
	}
	t.Cleanup(func() { db.Close() })
	return db
}

type schemaObject struct {
	Type    string  `json:"type"`
	Name    string  `json:"name"`
	TblName string  `json:"tbl_name"`
	SQL     *string `json:"sql"`
}

func dumpSchema(t *testing.T, db *sql.DB) []schemaObject {
	t.Helper()
	rows, err := db.Query(`select type, name, tbl_name, sql from sqlite_master
    where name not like 'sqlite_%' order by type, name`)
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var out []schemaObject
	for rows.Next() {
		var o schemaObject
		var sqlText sql.NullString
		if err := rows.Scan(&o.Type, &o.Name, &o.TblName, &sqlText); err != nil {
			t.Fatal(err)
		}
		if sqlText.Valid {
			v := sqlText.String
			o.SQL = &v
		}
		out = append(out, o)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return out
}

type ledgerRow struct {
	ID          string `json:"id"`
	Checksum    string `json:"checksum"`
	TimeApplied int64  `json:"time_applied"`
}

func dumpLedger(t *testing.T, db *sql.DB) []ledgerRow {
	t.Helper()
	rows, err := db.Query("select id, checksum, time_applied from tasks_schema_migration order by id")
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var out []ledgerRow
	for rows.Next() {
		var r ledgerRow
		if err := rows.Scan(&r.ID, &r.Checksum, &r.TimeApplied); err != nil {
			t.Fatal(err)
		}
		out = append(out, r)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return out
}

// schemaFromNode is the sqlite_master dump of a database the Node implementation
// created with runTasksDatabaseMigrations. Recorded by
// scripts/go-rewrite/crosscheck-taskindex.mjs (Node half) into testdata.
func schemaFromNode(t *testing.T, version string) []schemaObject {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(fixturesDir(t), "node-"+version+".schema.json"))
	if err != nil {
		t.Skipf("no Node fixture for %s: %v", version, err)
	}
	var out []schemaObject
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

func ledgerFromNode(t *testing.T, version string) []ledgerRow {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join(fixturesDir(t), "node-"+version+".ledger.json"))
	if err != nil {
		t.Skipf("no Node ledger fixture for %s: %v", version, err)
	}
	var out []ledgerRow
	if err := json.Unmarshal(raw, &out); err != nil {
		t.Fatal(err)
	}
	return out
}

// TestFreshDatabaseMatchesNodeSchema: an empty database migrated by Go must have
// exactly the sqlite_master contents Node produces, object for object. Every
// CREATE statement is compared as stored text, so indentation drift fails here.
func TestFreshDatabaseMatchesNodeSchema(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
	db := openMigrated(t, path)
	got := dumpSchema(t, db)
	want := schemaFromNode(t, "fresh")
	if len(got) != len(want) {
		t.Fatalf("object count: go %d, node %d", len(got), len(want))
	}
	for i := range want {
		if got[i].Type != want[i].Type || got[i].Name != want[i].Name || got[i].TblName != want[i].TblName {
			t.Fatalf("object %d: go %+v, node %+v", i, got[i], want[i])
		}
		if (want[i].SQL == nil) != (got[i].SQL == nil) {
			t.Fatalf("object %s: sql presence differs", got[i].Name)
		}
		if want[i].SQL != nil && *got[i].SQL != *want[i].SQL {
			t.Fatalf("object %s: sql text differs\n go:   %q\n node: %q", got[i].Name, *got[i].SQL, *want[i].SQL)
		}
	}
}

// TestFreshLedgerMatchesNode: the migration ledger (id, checksum) must match the
// rows Node writes, byte for byte on the checksum column.
func TestFreshLedgerMatchesNode(t *testing.T) {
	db := openMigrated(t, filepath.Join(t.TempDir(), "tasks-index.sqlite"))
	got := dumpLedger(t, db)
	want := ledgerFromNode(t, "fresh")
	if len(got) != len(want) || len(want) != 3 {
		t.Fatalf("ledger length: go %d, node %d, want 3 migrations", len(got), len(want))
	}
	for i := range want {
		if got[i].ID != want[i].ID || got[i].Checksum != want[i].Checksum {
			t.Fatalf("ledger row %d: go %+v, node %+v", i, got[i], want[i])
		}
	}
}

// TestMigrateEachVersionFromNodeFixture: for every recorded Node database
// version, Go opens it, runs the remaining migrations, and lands on the same
// final schema and ledger the Node fixture declares.
func TestMigrateEachVersionFromNodeFixture(t *testing.T) {
	versions := nodeFixtureVersions(t)
	if len(versions) == 0 {
		t.Skip("no per-version fixtures recorded yet")
	}
	for _, version := range versions {
		t.Run(version, func(t *testing.T) {
			src := filepath.Join(fixturesDir(t), "node-v"+version+".sqlite")
			if _, err := os.Stat(src); err != nil {
				t.Skipf("fixture %s missing: %v", src, err)
			}
			path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
			copyFile(t, src, path)
			// The fixture is a database that stopped at this version; after Go
			// applies the remainder it must equal what Node produces from nothing.
			// Comparing to the fresh Node fixtures is what makes that an equality
			// of state, not just "no error".
			db := openMigrated(t, path)
			wantSchema := schemaFromNode(t, "fresh")
			got := dumpSchema(t, db)
			if len(got) != len(wantSchema) {
				t.Fatalf("object count: go %d, node %d", len(got), len(wantSchema))
			}
			for i := range wantSchema {
				if got[i].Name != wantSchema[i].Name {
					t.Fatalf("object %d: go %q, node %q", i, got[i].Name, wantSchema[i].Name)
				}
				if *got[i].SQL != *wantSchema[i].SQL {
					t.Fatalf("object %s: sql text differs", got[i].Name)
				}
			}
			wantLedger := ledgerFromNode(t, "fresh")
			gotLedger := dumpLedger(t, db)
			if len(gotLedger) != len(wantLedger) {
				t.Fatalf("ledger length: go %d, node %d", len(gotLedger), len(wantLedger))
			}
			for i := range wantLedger {
				if gotLedger[i].ID != wantLedger[i].ID || gotLedger[i].Checksum != wantLedger[i].Checksum {
					t.Fatalf("ledger row %d: go %+v, node %+v", i, gotLedger[i], wantLedger[i])
				}
			}
		})
	}
}

func nodeFixtureVersions(t *testing.T) []string {
	t.Helper()
	entries, err := os.ReadDir(fixturesDir(t))
	if err != nil {
		return nil
	}
	var out []string
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(name, "node-v") || !strings.HasSuffix(name, ".sqlite") {
			continue
		}
		out = append(out, strings.TrimSuffix(strings.TrimPrefix(name, "node-v"), ".sqlite"))
	}
	return out
}

// TestSecondOpenDoesNotMigrate: re-opening a migrated database is a no-op with
// kind=none and zero executed migrations — the property the Node startup
// handover checks before reusing a prepared path.
func TestSecondOpenDoesNotMigrate(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
	openMigrated(t, path)
	var phases []string
	db, err := taskindex.Open(context.Background(), path, func(p taskindex.Progress) error {
		phases = append(phases, phaseKind(p))
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	for _, phase := range phases {
		if phase == "migrating" {
			t.Fatalf("re-open executed a migration: %v", phases)
		}
	}
	applied, err := taskindex.MigrationsApplied(context.Background(), db)
	if err != nil {
		t.Fatal(err)
	}
	if !applied {
		t.Fatal("MigrationsApplied is false on a migrated database")
	}
}

func phaseKind(p taskindex.Progress) string {
	kind := ""
	if p.Migration != nil {
		kind = ":" + p.Migration.Kind
	}
	return p.Phase + kind
}

// TestTamperedLedgerIsRefused: a historical migration is immutable. Rewriting its
// recorded checksum must fail the open rather than silently "upgrade".
func TestTamperedLedgerIsRefused(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
	db := openMigrated(t, path)
	if _, err := db.Exec("update tasks_schema_migration set checksum='deadbeef' where id='0001_adopt_task_schema'"); err != nil {
		t.Fatal(err)
	}
	db.Close()
	_, err := taskindex.Open(context.Background(), path, nil)
	if !errors.Is(err, taskindex.ErrChecksumMismatch) {
		t.Fatalf("want ErrChecksumMismatch, got %v", err)
	}
}

// TestNewerDatabaseIsRefused: a ledger holding a migration this binary does not
// know must be refused, not opened and downgraded.
func TestNewerDatabaseIsRefused(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
	db := openMigrated(t, path)
	if _, err := db.Exec("insert into tasks_schema_migration values ('0004_future_feature', 'abc', 1)"); err != nil {
		t.Fatal(err)
	}
	db.Close()
	_, err := taskindex.Open(context.Background(), path, nil)
	if !errors.Is(err, taskindex.ErrDatabaseNewer) {
		t.Fatalf("want ErrDatabaseNewer, got %v", err)
	}
}

// TestFailedMigrationRollsBack: a migration body that fails must leave the
// ledger and the schema untouched — the transaction is the boundary, not the
// individual statement.
func TestFailedMigrationRollsBack(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
	// Pre-create tasks with the 0001 column set absent, then make 0001 fail by
	// holding a conflicting table so CREATE TABLE IF NOT EXISTS is skipped and
	// the ALTER sequence hits the real error.
	raw, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := raw.Exec("create table automations (automation_id text primary key)"); err != nil {
		t.Fatal(err)
	}
	raw.Close()
	_, err = taskindex.Open(context.Background(), path, nil)
	if err == nil {
		t.Fatal("expected the adopt migration to fail on the conflicting automations table")
	}
	// After the rollback the ledger must not exist at all: the whole run is one
	// transaction, so a partial ledger would be an unrecoverable half-state.
	if _, statErr := os.Stat(path + "-wal"); statErr == nil {
		t.Log("wal sidecar present; contents are irrelevant after rollback")
	}
	db, err := sql.Open("sqlite", "file:"+path)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	var n int
	if err := db.QueryRow("select count(*) from sqlite_master where type='table' and name='tasks_schema_migration'").Scan(&n); err != nil {
		t.Fatal(err)
	}
	if n != 0 {
		t.Fatal("tasks_schema_migration survived a failed migration run")
	}
}

// TestConcurrentOpensSerialize: several processes may hold the same file during
// the strangler transition (Node host + Go front). Two concurrent opens must not
// produce SQLITE_BUSY or a duplicated ledger row.
func TestConcurrentOpensSerialize(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tasks-index.sqlite")
	// The first open creates the file so both goroutines race on the same one.
	openMigrated(t, path)
	done := make(chan error, 2)
	for range 2 {
		go func() {
			db, err := taskindex.Open(context.Background(), path, nil)
			if err == nil {
				db.Close()
			}
			done <- err
		}()
	}
	for range 2 {
		if err := <-done; err != nil {
			t.Fatalf("concurrent open: %v", err)
		}
	}
	db := openMigrated(t, path)
	if ledger := dumpLedger(t, db); len(ledger) != 3 {
		t.Fatalf("ledger has %d rows after concurrent opens, want 3", len(ledger))
	}
}

func copyFile(t *testing.T, src, dst string) {
	t.Helper()
	raw, err := os.ReadFile(src)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(dst, raw, 0o644); err != nil {
		t.Fatal(err)
	}
}
